// Karteikarten Personalführung – eigene Formulierungen
(window.FC=window.FC||{}).PF=[
 {id:'PF001',ch:'Personalbedarf',q:'Welche Fragen beantwortet die Personalbedarfsermittlung?',a:'Sie klärt, wie viele Mitarbeitende mit welcher Qualifikation zu welchem Zeitpunkt an welchem Ort benötigt werden.',pts:['Anzahl','Qualifikation','Zeitpunkt','Ort']},
 {id:'PF002',ch:'Personalbedarf',q:'Unterscheiden Sie quantitativen und qualitativen Personalbedarf.',a:'Quantitativ geht es um die Zahl der benötigten Personen bzw. Stellen, qualitativ um die benötigten Kompetenzen im Vergleich zum vorhandenen Können.',pts:['quantitativ: Anzahl der Personen','qualitativ: benötigte Qualifikation','qualitativ: Vergleich mit vorhandenem Können']},
 {id:'PF003',ch:'Personalbedarf',q:'Nennen Sie die fünf Bedarfsarten der quantitativen Personalbedarfsermittlung.',a:'Einsatzbedarf, Reservebedarf, Neubedarf, Ersatzbedarf und Freistellungsbedarf.',pts:['Einsatzbedarf','Reservebedarf','Neubedarf','Ersatzbedarf','Freistellungsbedarf']},
 {id:'PF004',ch:'Personalbedarf',q:'Ein Schweißer geht in Rente und die Stelle soll nachbesetzt werden. Um welche Bedarfsart handelt es sich?',a:'Um Ersatzbedarf – Neubedarf läge nur bei einer Erweiterung oder neuen Aufgabe vor.',pts:['Ersatzbedarf','kein Neubedarf','Neubedarf nur bei Erweiterung']},
 {id:'PF005',ch:'Personalbedarf',q:'Wozu dient der Reservebedarf und wie wird er vereinfacht berechnet?',a:'Er sichert die Abläufe bei Urlaub, Krankheit und sonstigen Fehlzeiten; vereinfacht Einsatzbedarf mal Ausfallquote.',tex:'R = E \\cdot q_\\text{A}',pts:['Puffer für Fehlzeiten','Einsatzbedarf mal Ausfallquote']},
 {id:'PF006',ch:'Personalbedarf',q:'Wie berechnet man den Nettopersonalbedarf?',a:'Bruttobedarf minus fortgeschriebener Bestand; der fortgeschriebene Bestand ist Stichtagsbestand minus Abgänge plus feststehende Zugänge.',tex:'N_\\text{netto} = B - (P_0 - A + Z)',pts:['Bruttobedarf als Ausgangsgröße','minus fortgeschriebener Bestand','Bestand minus Abgänge plus Zugänge']},
 {id:'PF007',ch:'Personalbedarf',q:'Bestand 50, 4 Abgänge, 1 Zugang, Bruttobedarf 52. Wie hoch ist der Nettobedarf?',a:'Fortgeschriebener Bestand 50 − 4 + 1 = 47; Nettobedarf 52 − 47 = 5 Personen (Unterdeckung).',pts:['Bestand fortschreiben: 47','Nettobedarf 5 Personen','Unterdeckung']},
 {id:'PF008',ch:'Personalbedarf',q:'Was bedeutet ein negativer Nettopersonalbedarf und wie kann der Meister reagieren?',a:'Es besteht Personalüberdeckung; Reaktionen sind z. B. Abbau von Mehrarbeit und Leiharbeit, Versetzung oder als letztes Mittel Freistellung.',pts:['Personalüberdeckung','Mehrarbeit/Leiharbeit abbauen','Versetzung','Freistellung als letztes Mittel']},
 {id:'PF009',ch:'Personalbedarf',q:'Nennen Sie je zwei interne und externe Einflussfaktoren auf den Personalbedarf.',a:'Intern z. B. Fluktuation und Altersstruktur, extern z. B. Konjunktur und technischer Wandel.',pts:['interner Faktor 1 (z. B. Fluktuation)','interner Faktor 2 (z. B. Altersstruktur)','externer Faktor 1 (z. B. Konjunktur)','externer Faktor 2 (z. B. technischer Wandel)']},
 {id:'PF010',ch:'Personalbedarf',q:'Unterscheiden Sie die strategische, taktische und operative Planungsebene.',a:'Strategisch: langfristig (ab ca. 3 Jahre), Geschäftsleitung. Taktisch: mittelfristig (1–3 Jahre), Bereichsleitung. Operativ: kurzfristig (Tage bis Wochen), Meister und Fachkräfte.',pts:['strategisch: langfristig, Geschäftsleitung','taktisch: 1–3 Jahre, Bereichsleitung','operativ: kurzfristig, Meister']},
 {id:'PF011',ch:'Personalbedarf',q:'Welche Rechte hat der Betriebsrat bei der Personalplanung?',a:'Der Arbeitgeber muss ihn rechtzeitig und umfassend unterrichten und mit ihm beraten (§ 92 BetrVG); der Betriebsrat kann innerbetriebliche Ausschreibung verlangen (§ 93 BetrVG).',pts:['Unterrichtung rechtzeitig und umfassend','§ 92 BetrVG','Beratung','interne Ausschreibung verlangen (§ 93)']},
 {id:'PF012',ch:'Personalbedarf',q:'Was zeigt ein Eignungsprofil?',a:'Den Vergleich von Anforderungsprofil der Stelle und Fähigkeitsprofil der Person; daraus folgen Eignung und Qualifizierungsbedarf.',pts:['Anforderungsprofil','Fähigkeitsprofil','Vergleich zeigt Qualifizierungsbedarf']},
 {id:'PF013',ch:'Bedarfsermittlung: Methoden',q:'Nennen Sie vier Methoden der Personalbedarfsermittlung.',a:'Z. B. deterministische Methode (Arbeitsplan), Kennzahlenmethode, Schätzverfahren (z. B. Delphi) und arbeitswissenschaftliche Verfahren (REFA, MTM).',pts:['deterministisch/Arbeitsplan','Kennzahlen','Schätzung/Delphi','REFA oder MTM']},
 {id:'PF014',ch:'Bedarfsermittlung: Methoden',q:'Wie berechnet man den Personalbedarf nach der deterministischen Methode?',a:'Gesamtzeitbedarf der Aufgaben geteilt durch die verfügbare Arbeitszeit je Person; das Ergebnis wird aufgerundet.',tex:'P = \\frac{T_\\text{ges}}{t_\\text{MA}}',pts:['Gesamtzeitbedarf im Zähler','Arbeitszeit je Person im Nenner','aufrunden']},
 {id:'PF015',ch:'Bedarfsermittlung: Methoden',q:'Ein Auftrag braucht 1.050 h im Monat, eine Person leistet 150 h. Wie viele Personen werden benötigt?',a:'1.050 h ÷ 150 h = 7 Personen.',pts:['Rechnung 1.050 ÷ 150','7 Personen']},
 {id:'PF016',ch:'Bedarfsermittlung: Methoden',q:'Was ist die Delphi-Methode?',a:'Eine mehrstufige, oft anonyme Expertenbefragung mit Begründungen und Rückkopplung, bis eine konsensnahe Prognose entsteht.',pts:['Expertenbefragung','mehrere Runden','Begründung und Rückkopplung','Konsens als Ziel']},
 {id:'PF017',ch:'Bedarfsermittlung: Methoden',q:'Welche Annahme liegt der Kennzahlenmethode zugrunde und welche Schwäche hat sie?',a:'Sie unterstellt, dass eine in der Vergangenheit stabile Verhältniszahl (z. B. Umsatz je Kopf) weiter gilt; Produktivitätssprünge wie Automatisierung bleiben unberücksichtigt.',pts:['stabile Kennzahl aus der Vergangenheit','gleiche Bedingungen unterstellt','Strukturbrüche nicht erfasst']},
 {id:'PF018',ch:'Bedarfsermittlung: Methoden',q:'Wie ermittelt man den Personalbedarf für einen Zusatzauftrag?',a:'Stückzahl geteilt durch Leistung je Stunde mal verfügbare Stunden je Person; aufrunden.',tex:'P = \\frac{m}{r \\cdot t_\\text{v}}',pts:['Stückzahl im Zähler','Stück je Stunde mal Stunden im Nenner','aufrunden']},
 {id:'PF019',ch:'Personalauswahl',q:'Nennen Sie die vier Grundschritte der Personalauswahl.',a:'Anforderungsprofil festlegen, Profil der Person ermitteln, beide zum Eignungsprofil vergleichen, Entscheidung über Einstellung oder Absage.',pts:['Anforderungsprofil','Profil der Person','Vergleich/Eignungsprofil','Entscheidung']},
 {id:'PF020',ch:'Personalauswahl',q:'Welche Rechte hat der Betriebsrat bei einer Einstellung?',a:'In Unternehmen mit mehr als 20 wahlberechtigten Beschäftigten muss er zustimmen (§ 99 BetrVG); er ist vorher zu unterrichten und kann aus den gesetzlichen Gründen binnen einer Woche widersprechen.',pts:['Zustimmung nach § 99 BetrVG','mehr als 20 Wahlberechtigte','vorherige Unterrichtung','Widerspruch binnen einer Woche']},
 {id:'PF021',ch:'Personalauswahl',q:'Was muss der Betrieb bei einem Personalfragebogen beachten?',a:'Nur stellenbezogene, zulässige Fragen; der Einsatz braucht die Zustimmung des Betriebsrats (§ 94 BetrVG).',pts:['nur stellenbezogene Fragen','Zustimmung Betriebsrat','§ 94 BetrVG']},
 {id:'PF022',ch:'Personalauswahl',q:'Unterscheiden Sie einfaches und qualifiziertes Arbeitszeugnis.',a:'Das einfache Zeugnis enthält Art und Dauer der Tätigkeit, das qualifizierte zusätzlich Leistung und Verhalten; es ist auf Verlangen auszustellen.',pts:['einfach: Art und Dauer','qualifiziert: plus Leistung und Verhalten','qualifiziert auf Verlangen']},
 {id:'PF023',ch:'Personalauswahl',q:'Welche Grundsätze gelten für ein Arbeitszeugnis?',a:'Es muss wahr, wohlwollend sowie klar und verständlich sein und darf keine versteckten Aussagen enthalten (§ 109 GewO).',pts:['Wahrheit','Wohlwollen','Klarheit, keine Geheimcodes','§ 109 GewO']},
 {id:'PF024',ch:'Personalauswahl',q:'Nennen Sie drei Gütekriterien für Auswahltests.',a:'Objektivität, Reliabilität und Validität.',pts:['Objektivität','Reliabilität','Validität']},
 {id:'PF025',ch:'Personalauswahl',q:'Was ist ein Assessment-Center?',a:'Ein Auswahlverfahren, das mehrere Übungen kombiniert und die Zielposition simuliert; mehrere Beobachter bewerten, am Ende gibt es Feedback.',pts:['Kombination mehrerer Übungen','Simulation der Zielposition','mehrere Beobachter','Feedback an Teilnehmende']},
 {id:'PF026',ch:'Personalauswahl',q:'Nennen Sie vier typische Übungen eines Assessment-Centers.',a:'Z. B. Postkorb, Rollenspiel, Gruppendiskussion und Präsentation.',pts:['Postkorb','Rollenspiel','Gruppendiskussion','Präsentation']},
 {id:'PF027',ch:'Personalauswahl',q:'Ein Bewerber wird gefragt, ob er Gewerkschaftsmitglied ist. Wie ist die Rechtslage?',a:'Die Frage ist unzulässig; der Bewerber darf sie wahrheitswidrig beantworten. Benachteiligungen können zudem gegen AGG bzw. Koalitionsfreiheit verstoßen.',pts:['Frage unzulässig','Recht zur Lüge','Benachteiligungsverbot']},
 {id:'PF028',ch:'Personalauswahl',q:'Wann ist eine Einstellungsuntersuchung erlaubt bzw. Pflicht?',a:'Grundsätzlich nur mit Einwilligung; bei Jugendlichen ist eine ärztliche Erstuntersuchung Pflicht (§ 32 JArbSchG).',pts:['Einwilligung erforderlich','Pflicht bei Jugendlichen','§ 32 JArbSchG']},
 {id:'PF029',ch:'Personalauswahl',q:'Welche Merkmale schützt das AGG bei der Auswahl?',a:'Ethnische Herkunft, Geschlecht, Religion oder Weltanschauung, Behinderung, Alter und sexuelle Identität.',pts:['ethnische Herkunft','Geschlecht','Religion/Weltanschauung','Behinderung','Alter','sexuelle Identität']},
 {id:'PF030',ch:'Personalauswahl',q:'Worin unterscheiden sich Leistungsfähigkeit und Leistungsbereitschaft – und wo setzt der Meister an?',a:'Leistungsfähigkeit (Begabung, Wissen) ist stabil und kaum beeinflussbar; Leistungsbereitschaft (Motivation, Konzentration) ist durch Führung beeinflussbar – hier setzt der Meister an.',pts:['Fähigkeit: Begabung, stabil','Bereitschaft: Motivation','Führung wirkt auf die Bereitschaft']},
 {id:'PF031',ch:'Einsatz und Onboarding',q:'Nennen Sie vier Lösungswege bei einem Interessenkonflikt zur Urlaubsplanung.',a:'Abwarten, Losentscheid (wenn vereinbart), Anordnung durch Vorgesetzte, Kompromiss oder Win-win-Lösung.',pts:['Losentscheid nach Vereinbarung','Anordnung','Kompromiss','Win-win-Lösung']},
 {id:'PF032',ch:'Einsatz und Onboarding',q:'Welches Mitbestimmungsrecht hat der Betriebsrat bei Urlaubsgrundsätzen?',a:'Allgemeine Urlaubsgrundsätze und der Urlaubsplan sind mitbestimmungspflichtig (§ 87 Abs. 1 Nr. 5 BetrVG).',pts:['Mitbestimmung','Urlaubsgrundsätze und Urlaubsplan','§ 87 Abs. 1 Nr. 5 BetrVG']},
 {id:'PF033',ch:'Einsatz und Onboarding',q:'Nennen Sie die drei Phasen des Onboardings.',a:'Vorbereitung, Einführung bzw. Einarbeitung und Nachbereitung.',pts:['Vorbereitung','Einführung/Einarbeitung','Nachbereitung']},
 {id:'PF034',ch:'Einsatz und Onboarding',q:'Was bereitet der Meister vor dem ersten Arbeitstag vor?',a:'Arbeitsplatz und Arbeitsmittel, Zugänge, Unterlagen, Information des Teams und Benennung eines Paten.',pts:['Arbeitsplatz und Arbeitsmittel','Zugänge/Unterlagen','Team informieren','Paten benennen']},
 {id:'PF035',ch:'Einsatz und Onboarding',q:'Welche Informationen muss der Arbeitgeber neuen Beschäftigten geben?',a:'Über Aufgabe und Verantwortung, die Einordnung in den Ablauf sowie Unfall- und Gesundheitsgefahren und Schutzmaßnahmen (§ 81 BetrVG); dazu die Unterweisung nach Arbeitsschutzgesetz.',pts:['Aufgabe und Verantwortung','Unfall- und Gesundheitsgefahren','§ 81 BetrVG','Unterweisung Arbeitsschutz']},
 {id:'PF036',ch:'Einsatz und Onboarding',q:'Was sollte vor Ende der Probezeit geschehen?',a:'Ein Abschlussgespräch mit Bilanz der Einarbeitung, Feedback in beide Richtungen und vereinbarten Förderzielen.',pts:['Bilanzgespräch','Feedback','Förderziele vereinbaren']},
 {id:'PF037',ch:'Einsatz und Onboarding',q:'Unterscheiden Sie Mentor, Coach und Mediator.',a:'Der Mentor fördert Nachwuchskräfte, der Coach begleitet meist Führungskräfte in Umbrüchen, der Mediator vermittelt neutral in eskalierten Konflikten.',pts:['Mentor: Nachwuchsförderung','Coach: Begleitung von Führungskräften','Mediator: neutrale Konfliktvermittlung']},
 {id:'PF038',ch:'Anforderungsprofil und Stellen',q:'Unterscheiden Sie Muss- und Wunschanforderungen.',a:'Muss-Anforderungen sind unverzichtbar und werden in der Vorauswahl geprüft; Wunschanforderungen entscheiden zwischen geeigneten Bewerbungen.',pts:['Muss: unverzichtbar','Muss: Vorauswahl','Wunsch: Endauswahl']},
 {id:'PF039',ch:'Anforderungsprofil und Stellen',q:'Was ist eine Aufgabenanalyse?',a:'Die stufenweise Zerlegung einer Hauptaufgabe in Teilaufgaben, bis sich ihnen konkrete Anforderungen an die Person zuordnen lassen.',pts:['Hauptaufgabe zerlegen','Teilaufgaben','Anforderungen ableiten']},
 {id:'PF040',ch:'Anforderungsprofil und Stellen',q:'Warum müssen Anforderungsprofile fortgeschrieben werden?',a:'Weil sich Technik, Organisation und Leitbild ändern und damit die Anforderungen an die Stelle.',pts:['Technik ändert sich','Organisation ändert sich','Leitbild/Kultur ändert sich']},
 {id:'PF041',ch:'Anforderungsprofil und Stellen',q:'Nennen Sie fünf Anforderungen an Führungskräfte.',a:'Z. B. Kommunikationsfähigkeit, Entscheidungsfähigkeit, Teamfähigkeit, Empathie und Integrität.',pts:['Kommunikationsfähigkeit','Entscheidungsfähigkeit','Teamfähigkeit','Empathie','Integrität']},
 {id:'PF042',ch:'Anforderungsprofil und Stellen',q:'Nennen Sie die drei Bausteine einer Stellenbeschreibung.',a:'Instanzenbild, Aufgabenbild und Leistungsbild.',pts:['Instanzenbild','Aufgabenbild','Leistungsbild']},
 {id:'PF043',ch:'Anforderungsprofil und Stellen',q:'Was gehört in das Instanzenbild einer Stellenbeschreibung?',a:'Stellenbezeichnung, Einordnung, Über- und Unterstellung, Vertretung sowie Verbindungen zu anderen Stellen.',pts:['Bezeichnung','Über- und Unterstellung','Vertretung','Verbindungen zu anderen Stellen']},
 {id:'PF044',ch:'Anforderungsprofil und Stellen',q:'Unterscheiden Sie Stellenplan und Stellenbesetzungsplan.',a:'Der Stellenplan zeigt die vorgesehenen Stellen in der Aufbauorganisation, der Stellenbesetzungsplan ordnet ihnen die konkreten Personen zu.',pts:['Stellenplan: Soll-Stellen','Besetzungsplan: Personen zugeordnet']},
 {id:'PF045',ch:'Anforderungsprofil und Stellen',q:'Was zeigt eine Funktionsbeschreibung bzw. ein Funktionsdiagramm?',a:'Welche Stelle bei einer Aufgabe welche Funktion ausübt, z. B. entscheiden, planen, ausführen, kontrollieren, informiert werden.',pts:['Aufgaben gegen Stellen','Funktion je Stelle','z. B. entscheiden, ausführen, kontrollieren']},
 {id:'PF046',ch:'Delegation',q:'Was versteht man unter Delegation?',a:'Die Übertragung einer klar umrissenen Aufgabe mit den nötigen Befugnissen und der Handlungsverantwortung auf geeignete Mitarbeitende.',pts:['Aufgabe übertragen','Befugnisse mit übertragen','Handlungsverantwortung übertragen']},
 {id:'PF047',ch:'Delegation',q:'Was besagt das Kongruenzprinzip der Delegation?',a:'Aufgabe, Befugnis (Kompetenz) und Verantwortung müssen übereinstimmen.',pts:['Aufgabe','Befugnis','Verantwortung','müssen übereinstimmen']},
 {id:'PF048',ch:'Delegation',q:'Welche Verantwortung bleibt bei der Führungskraft, wenn sie delegiert?',a:'Die Führungsverantwortung: richtige Auswahl, Information, Anleitung und Kontrolle.',pts:['Führungsverantwortung','Auswahl','Anleitung','Kontrolle']},
 {id:'PF049',ch:'Delegation',q:'Nennen Sie vier Aufgaben, die eine Führungskraft nicht delegieren sollte.',a:'Ziele setzen und planen, Stellen besetzen, Mitarbeiterführung und Leistungsbeurteilung (auch Erfolgskontrolle, Befugnisse abgrenzen).',pts:['Zielsetzung/Planung','Stellenbesetzung','Mitarbeiterführung','Leistungsbeurteilung']},
 {id:'PF050',ch:'Delegation',q:'Wie geht man nach dem Eisenhower-Prinzip mit A-, B-, C- und D-Aufgaben um?',a:'A (wichtig, dringend) sofort selbst, B (wichtig, nicht dringend) terminieren oder delegieren, C (dringend, nicht wichtig) delegieren, D (weder noch) ablegen.',pts:['A sofort selbst erledigen','B terminieren','C delegieren','D ablegen/Papierkorb']},
 {id:'PF051',ch:'Delegation',q:'Was ist der Unterschied zwischen Delegation nach Eisenhower und Management by Delegation?',a:'Eisenhower dient der Entlastung und Selbstorganisation, auch einfache Aufgaben werden abgegeben; Management by Delegation soll fördern, die Aufgabe muss zum Können passen.',pts:['Eisenhower: Entlastung','MbD: Förderung','Aufgabe passend zum Können']},
 {id:'PF052',ch:'Delegation',q:'Nennen Sie fünf Inhalte eines Delegationsgesprächs.',a:'Begründung der Auswahl, Aufgabe und Ziel, Termin, Ressourcen und Befugnisse sowie vereinbarte Kontrolle bzw. Rückmeldung.',pts:['Auswahl begründen','Aufgabe und Ziel','Termin','Ressourcen und Befugnisse','Kontrolle vereinbaren']},
 {id:'PF053',ch:'Delegation',q:'Ein Mitarbeiter bringt delegierte Aufgaben immer wieder zurück. Wie reagiert der Meister?',a:'Rückdelegation abwehren: Unterstützung und Rat geben, aber Entscheidung und Erledigung beim Mitarbeiter lassen; ggf. Befugnisse und Qualifikation prüfen.',pts:['Rückdelegation abwehren','beraten statt übernehmen','Befugnisse/Qualifikation prüfen']},
 {id:'PF054',ch:'Delegation',q:'Welche Befugnisse braucht ein Mitarbeiter, der den Meister mehrere Wochen vertritt?',a:'Z. B. Weisungsbefugnis, Unterschrifts- bzw. Freigaberechte, Zugangsrechte zu Systemen und Teilnahme an Leitungsbesprechungen.',pts:['Weisungsbefugnis','Unterschriftsrecht','Systemzugänge','Teilnahme an Besprechungen']},
 {id:'PF055',ch:'Kontrolle',q:'Beschreiben Sie den Regelkreis der Kontrolle.',a:'Soll festlegen, Ist erfassen, vergleichen, Ursachen der Abweichung klären, korrigieren und erneut prüfen, bis das Ziel erreicht ist.',pts:['Soll festlegen','Ist erfassen','Soll-Ist-Vergleich','Ursachen klären','korrigieren und erneut prüfen']},
 {id:'PF056',ch:'Kontrolle',q:'Unterscheiden Sie Prozess- und Ergebniskontrolle.',a:'Prozesskontrolle prüft während der Ausführung, wenn Fehler später nicht sichtbar sind; Ergebniskontrolle prüft nur das Endergebnis und lässt den Weg frei.',pts:['Prozesskontrolle: während der Ausführung','für später unsichtbare Fehler','Ergebniskontrolle: Endergebnis']},
 {id:'PF057',ch:'Kontrolle',q:'Soll 2 % Ausschuss, Ist 3 %. Berechnen Sie die absolute und relative Abweichung.',a:'Absolut 1 Prozentpunkt; relativ (3 − 2) ÷ 2 · 100 % = 50 % über Soll.',tex:'\\Delta_\\text{rel} = \\frac{\\text{Ist} - \\text{Soll}}{\\text{Soll}} \\cdot 100\\,\\%',pts:['1 Prozentpunkt absolut','50 % relativ']},
 {id:'PF058',ch:'Kontrolle',q:'Nennen Sie vier mögliche Ursachen von Soll-Ist-Abweichungen.',a:'Ungenaue Ziele, unvollständige Planung, technische oder organisatorische Mängel, menschliches Fehlverhalten (auch äußere Einflüsse).',pts:['ungenaue Ziele','unvollständige Planung','technische/organisatorische Mängel','menschliches Fehlverhalten']},
 {id:'PF059',ch:'Kontrolle',q:'Welche Vorteile hat Selbstkontrolle für die Mitarbeitenden?',a:'Sie stärkt Verantwortung und Motivation, Fehler werden früh am Arbeitsplatz erkannt.',pts:['mehr Verantwortung','mehr Motivation','frühe Fehlererkennung']},
 {id:'PF060',ch:'Kommunikation',q:'Nennen Sie drei Axiome von Watzlawick.',a:'Man kann nicht nicht kommunizieren; jede Kommunikation hat Inhalts- und Beziehungsaspekt; Kommunikation ist digital und analog (weitere: Interpunktion, symmetrisch/komplementär).',pts:['nicht nicht kommunizieren','Inhalts- und Beziehungsaspekt','digital und analog']},
 {id:'PF061',ch:'Kommunikation',q:'Was bedeutet „Man kann nicht nicht kommunizieren“ für den Meister?',a:'Auch Schweigen, Blicke oder Wegsehen werden als Botschaft verstanden, z. B. wenn er an einer Störung wortlos vorbeigeht.',pts:['jedes Verhalten ist Botschaft','auch Schweigen wirkt','Vorbild im Verhalten']},
 {id:'PF062',ch:'Kommunikation',q:'Nennen Sie die vier Seiten einer Nachricht nach Schulz von Thun.',a:'Sachinhalt, Selbstoffenbarung, Beziehung und Appell.',pts:['Sachinhalt','Selbstoffenbarung','Beziehung','Appell']},
 {id:'PF063',ch:'Kommunikation',q:'Ein Mitarbeiter sagt: „Die Säge ist schon wieder stumpf!“ Ordnen Sie die vier Seiten zu.',a:'Sachinhalt: Band abgenutzt; Selbstoffenbarung: ich bin genervt; Beziehung: du kümmerst dich nicht; Appell: wechsle das Band.',pts:['Sache: Band stumpf','Selbstoffenbarung: Ärger','Beziehung: Vorwurf','Appell: Band wechseln']},
 {id:'PF064',ch:'Kommunikation',q:'Worin liegt die Bedeutung der Rückmeldung (Feedback) im Kommunikationsmodell?',a:'Nur sie zeigt dem Sender, ob die Nachricht so verstanden wurde wie gemeint.',pts:['Kontrolle des Verständnisses','Missverständnisse aufdecken']},
 {id:'PF065',ch:'Kommunikation',q:'Nennen Sie vier Störungen der Kommunikation im Betrieb.',a:'Lärm, Zeitdruck, Fachsprache und Hierarchie (auch verkürzte Kurzmails, Schichtbetrieb).',pts:['Lärm','Zeitdruck','Fachsprache','Hierarchie']},
 {id:'PF066',ch:'Kommunikation',q:'Nennen Sie je einen Vor- und Nachteil digitaler Kommunikation.',a:'Vorteil: schnell, ortsunabhängig, dokumentiert; Nachteil: Zwischentöne und Körpersprache fehlen, Missverständnisse.',pts:['Vorteil: schnell/ortsunabhängig','Nachteil: fehlende Zwischentöne']},
 {id:'PF067',ch:'Kommunikation',q:'Schichtübergaben scheitern in der lauten Halle. Welche Maßnahmen schlagen Sie vor?',a:'Kurze Überlappung, Übergabe an einem ruhigen Ort, schriftliche Checkliste mit Rückfrage und Unterschrift beider Schichtführer.',pts:['Schichtüberlappung','ruhiger Ort','Checkliste','Rückfrage/Bestätigung']},
 {id:'PF068',ch:'Kommunikation',q:'Nennen Sie die vier Verhaltensgrundlagen der Kooperation.',a:'Offenheit, Vertrauen, Hilfsbereitschaft und Mut.',pts:['Offenheit','Vertrauen','Hilfsbereitschaft','Mut']},
 {id:'PF069',ch:'Kommunikation',q:'Was sagt die Reihe „gesagt – gehört – verstanden – einverstanden – angewendet – beibehalten“ aus?',a:'Jede Stufe ist nicht automatisch erreicht; der Meister muss Verständnis, Zustimmung und Umsetzung prüfen.',pts:['Stufen nicht automatisch erreicht','Verständnis prüfen','Umsetzung prüfen']},
 {id:'PF070',ch:'Gesprächsführung',q:'Nennen Sie die Phasen eines Mitarbeitergesprächs.',a:'Vorbereitung, Einleitung, Hauptteil, Abschluss und Nachbereitung.',pts:['Vorbereitung','Einleitung','Hauptteil','Abschluss','Nachbereitung']},
 {id:'PF071',ch:'Gesprächsführung',q:'Was gehört zur Vorbereitung eines Mitarbeitergesprächs?',a:'Aufgaben und Leistung der Person, Ergebnisse des letzten Gesprächs, Gesprächsziel, Termin und störungsfreier Raum.',pts:['Leistung/Aufgaben kennen','letzte Vereinbarungen','Ziel festlegen','Termin und Raum']},
 {id:'PF072',ch:'Gesprächsführung',q:'Nennen Sie vier Regeln für den Hauptteil eines Mitarbeitergesprächs.',a:'Mitarbeitende überwiegend sprechen lassen, aktiv zuhören, offene Fragen stellen, keine Suggestivfragen, zusammenfassen.',pts:['sprechen lassen','aktiv zuhören','offene Fragen','keine Suggestivfragen']},
 {id:'PF073',ch:'Gesprächsführung',q:'Wie ist ein Kritikgespräch aufgebaut?',a:'Beziehung herstellen, Sachverhalt konkret schildern, Sicht der Person anhören, Ursachen klären, Lösung finden lassen, Vereinbarung treffen, positiv abschließen.',pts:['Beziehung herstellen','Sachverhalt schildern','Person anhören','Lösung vereinbaren','positiv abschließen']},
 {id:'PF074',ch:'Gesprächsführung',q:'Ein Mitarbeiter trägt an der Drehmaschine keine Schutzbrille. Wie führen Sie das Gespräch?',a:'Zeitnah unter vier Augen, Beobachtung als Ich-Botschaft schildern, Gründe anhören, Lösung vereinbaren, Konsequenz bei Wiederholung klar machen, dokumentieren und nachhalten.',pts:['unter vier Augen, zeitnah','Ich-Botschaft','Gründe anhören','Vereinbarung','dokumentieren und nachhalten']},
 {id:'PF075',ch:'Gesprächsführung',q:'Nennen Sie vier Regeln für Anerkennung.',a:'Zeitnah, konkret, glaubwürdig, gleiche Maßstäbe für alle, nicht als Mittel zum Zweck.',pts:['zeitnah','konkret','glaubwürdig','gleiche Maßstäbe']},
 {id:'PF076',ch:'Gesprächsführung',q:'Unterscheiden Sie offene und geschlossene Fragen mit Beispiel.',a:'Offene Fragen (W-Fragen) laden zum Erzählen ein, z. B. „Wie kam es dazu?“; geschlossene sind mit Ja/Nein beantwortbar, z. B. „Haben Sie die Anweisung erhalten?“',pts:['offen: W-Frage, Erzählen','geschlossen: Ja/Nein','je ein Beispiel']},
 {id:'PF077',ch:'Gesprächsführung',q:'Wann wählen Sie ein Einzel-, wann ein Gruppengespräch?',a:'Einzelgespräch bei persönlichen Belangen, Kritik oder Lob einzelner; Gruppengespräch bei Sachthemen, die alle betreffen.',pts:['Einzel: persönliche Themen','Einzel: Kritik','Gruppe: Themen für alle']},
 {id:'PF078',ch:'Gesprächsführung',q:'Nennen Sie die drei Argumentationsebenen in steigender Stärke.',a:'Plausibilität (Erfahrung), Rationalität (Zahlen, Logik) und Ethik bzw. Moral.',pts:['Plausibilität','Rationalität','Ethik/Moral']},
 {id:'PF079',ch:'Gesprächsführung',q:'Wie gehen Sie mit privaten Problemen eines Mitarbeiters im Gespräch um?',a:'Empathisch zuhören, nichts erzwingen, keine Hilfe versprechen, die man nicht leisten kann, und auf Fachstellen verweisen.',pts:['nichts erzwingen','empathisch zuhören','keine falschen Versprechen','an Fachstellen verweisen']},
 {id:'PF080',ch:'Führungsstile und -modelle',q:'Nennen Sie die drei klassischen Führungsstile nach Lewin.',a:'Autoritär, kooperativ (demokratisch) und Laissez-faire.',pts:['autoritär','kooperativ','Laissez-faire']},
 {id:'PF081',ch:'Führungsstile und -modelle',q:'Nennen Sie je einen Vor- und Nachteil des autoritären Führungsstils.',a:'Vorteil: schnelle Entscheidungen, z. B. in Krisen; Nachteil: wenig Initiative und Motivation, Abhängigkeit von der Führungskraft.',pts:['Vorteil: schnell','Nachteil: wenig Initiative']},
 {id:'PF082',ch:'Führungsstile und -modelle',q:'Nennen Sie je einen Vor- und Nachteil des kooperativen Führungsstils.',a:'Vorteil: Motivation, Ideen und Akzeptanz; Nachteil: zeitaufwendige Entscheidungen.',pts:['Vorteil: Motivation/Akzeptanz','Nachteil: zeitaufwendig']},
 {id:'PF083',ch:'Führungsstile und -modelle',q:'Was ist Management by Objectives?',a:'Führen mit vereinbarten Zielen, deren Erreichung regelmäßig gemeinsam überprüft wird; der Weg bleibt den Mitarbeitenden überlassen.',pts:['Ziele vereinbaren','regelmäßige Überprüfung','Weg frei wählbar']},
 {id:'PF084',ch:'Führungsstile und -modelle',q:'Welche Anforderungen stellt die SMART-Regel an Ziele?',a:'Spezifisch, messbar, akzeptiert bzw. attraktiv, realistisch und terminiert.',pts:['spezifisch','messbar','akzeptiert','realistisch','terminiert']},
 {id:'PF085',ch:'Führungsstile und -modelle',q:'Formulieren Sie ein SMART-Ziel für eine Fräszelle.',a:'Z. B.: „Die Rüstzeit je Wechsel sinkt bis 30.09. von 45 auf 35 Minuten, gemessen im Betriebsdatenerfassungssystem.“',pts:['konkreter Gegenstand','messbare Größe','Termin','Messmethode']},
 {id:'PF086',ch:'Führungsstile und -modelle',q:'Was beschreibt das Verhaltensgitter von Blake und Mouton?',a:'Führungsverhalten in zwei Dimensionen, Sachorientierung und Mitarbeiterorientierung je 1–9; Ideal ist 9.9 (Teammanagement).',pts:['Sachorientierung','Mitarbeiterorientierung','Skala 1–9','Ideal 9.9']},
 {id:'PF087',ch:'Führungsstile und -modelle',q:'Erläutern Sie situatives Führen nach Hersey/Blanchard.',a:'Der Führungsstil richtet sich nach dem Reifegrad: geringe Reife anweisen, dann überzeugen, dann beteiligen, bei hoher Reife delegieren.',pts:['Reifegrad entscheidet','anweisen','überzeugen','beteiligen','delegieren']},
 {id:'PF088',ch:'Führungsstile und -modelle',q:'Wie berechnet man die Gesamtanlageneffektivität (OEE)?',a:'Verfügbarkeitsgrad mal Leistungsgrad mal Qualitätsgrad, jeweils als Dezimalzahl.',tex:'\\text{OEE} = V \\cdot L \\cdot Q',pts:['Verfügbarkeit','mal Leistung','mal Qualität']},
 {id:'PF089',ch:'Führungsstile und -modelle',q:'Welche Mitbestimmung besteht bei Zielprämien?',a:'Leistungsbezogene Entgelte und Prämien sind mitbestimmungspflichtig (§ 87 Abs. 1 Nr. 10 und 11 BetrVG).',pts:['Mitbestimmung','§ 87 Abs. 1 Nr. 10/11 BetrVG']},
 {id:'PF090',ch:'Führungsstile und -modelle',q:'Welche vier Felder hat das Johari-Fenster?',a:'Arena (öffentlich), blinder Fleck, Fassade und Unbekanntes.',pts:['Arena','blinder Fleck','Fassade','Unbekanntes']},
 {id:'PF091',ch:'Führungsstile und -modelle',q:'Wie kann eine Führungskraft ihren blinden Fleck verkleinern?',a:'Durch Feedback der Mitarbeitenden, z. B. Polaritätenprofil oder 360-Grad-Feedback, und Vergleich von Selbst- und Fremdbild.',pts:['Feedback einholen','Polaritätenprofil/360 Grad','Selbst- und Fremdbild vergleichen']},
 {id:'PF092',ch:'Konfliktmanagement',q:'Nennen Sie vier Arten sachlicher Konflikte.',a:'Ziel- bzw. Bewertungskonflikt, Beurteilungs- bzw. Wegekonflikt, Verteilungskonflikt und Beziehungskonflikt.',pts:['Bewertungs-/Zielkonflikt','Beurteilungs-/Wegekonflikt','Verteilungskonflikt','Beziehungskonflikt']},
 {id:'PF093',ch:'Konfliktmanagement',q:'Zwei Meister streiten um den einzigen Hallenkran. Welche Konfliktart liegt vor?',a:'Ein Verteilungskonflikt um knappe Ressourcen.',pts:['Verteilungskonflikt','knappe Ressource']},
 {id:'PF094',ch:'Konfliktmanagement',q:'Was ist ein Rollenkonflikt? Nennen Sie ein Beispiel.',a:'Unvereinbare Erwartungen an eine Person aus verschiedenen Rollen, z. B. ein Meister, der im Verein Spieler unter dem Trainer ist, den er im Betrieb führt.',pts:['widersprüchliche Erwartungen','mehrere Rollen einer Person','Beispiel genannt']},
 {id:'PF095',ch:'Konfliktmanagement',q:'Nennen Sie fünf Konfliktsymptome.',a:'Widerstand, Feindseligkeit, Sturheit, Flucht (z. B. hohe Fehlzeiten) und Desinteresse.',pts:['Widerstand','Feindseligkeit','Sturheit','Flucht/Fehlzeiten','Desinteresse']},
 {id:'PF096',ch:'Konfliktmanagement',q:'Beschreiben Sie den Ablauf der Konfliktbearbeitung.',a:'Symptome wahrnehmen, Konflikt analysieren, Lösungsstrategien für Sach- und Beziehungsebene entwickeln, Lösung vereinbaren und nachhalten.',pts:['wahrnehmen','analysieren','Strategie Sach- und Beziehungsebene','vereinbaren und nachhalten']},
 {id:'PF097',ch:'Konfliktmanagement',q:'Erläutern Sie die Drei-Stufen-Strategie der Konfliktlösung.',a:'Zuerst klären die Beteiligten selbst, dann vermittelt eine neutrale Person, zuletzt entscheidet eine übergeordnete Instanz, damit der Betrieb weiterläuft.',pts:['Beteiligte selbst','neutrale Vermittlung','Entscheidung übergeordneter Instanz']},
 {id:'PF098',ch:'Konfliktmanagement',q:'Nennen Sie die drei Ebenen des Eskalationsmodells nach Glasl.',a:'Win-win (Stufen 1–3), win-lose (4–6) und lose-lose (7–9).',pts:['win-win 1–3','win-lose 4–6','lose-lose 7–9']},
 {id:'PF099',ch:'Konfliktmanagement',q:'Was kennzeichnet eine Mediation?',a:'Eine neutrale dritte Person ohne Entscheidungsbefugnis unterstützt die Parteien, die freiwillig und vertraulich selbst eine Lösung erarbeiten.',pts:['neutrale dritte Person','keine Entscheidungsbefugnis','Parteien lösen selbst','freiwillig und vertraulich']},
 {id:'PF100',ch:'Konfliktmanagement',q:'Nennen Sie die Phasen einer Mediation.',a:'Auftragsklärung und Regeln, Themensammlung, Positionen und Interessen klären, Lösungen entwickeln, schriftliche Vereinbarung.',pts:['Auftrag und Regeln','Themen sammeln','Interessen klären','Lösungen entwickeln','Vereinbarung']},
 {id:'PF101',ch:'Konfliktmanagement',q:'Ihr Vorgesetzter will Ihre Azubis während eines Großauftrags abziehen. Wie gehen Sie sachorientiert vor?',a:'Fakten zu Kapazität und Terminen aufbereiten, Folgen beider Varianten aufzeigen, Alternativen anbieten und einen gemeinsam getragenen Kompromiss vereinbaren.',pts:['Zahlen und Fakten','Folgen aufzeigen','Alternativen anbieten','gemeinsame Vereinbarung']},
 {id:'PF102',ch:'Konfliktmanagement',q:'Welche Frist gilt für Ansprüche nach dem AGG?',a:'Ansprüche auf Entschädigung oder Schadensersatz müssen binnen zwei Monaten schriftlich geltend gemacht werden (§ 15 Abs. 4 AGG).',pts:['zwei Monate','schriftlich','§ 15 Abs. 4 AGG']},
 {id:'PF103',ch:'Konfliktmanagement',q:'Nennen Sie vier Maßnahmen zur Konfliktprävention im Betrieb.',a:'Bekannte Anlaufstellen (z. B. Ombudsperson), geschulte Konfliktbeauftragte, transparente Abläufe und Regelungen, Dokumentation.',pts:['Anlaufstellen','Konfliktbeauftragte','transparente Abläufe','Dokumentation']},
 {id:'PF104',ch:'KVP und Vorschlagswesen',q:'Nennen Sie vier Grundgedanken von KVP bzw. Kaizen.',a:'Standards sind die Basis, alles ist weiter verbesserbar, kleine Schritte statt großer Sprünge, alle Mitarbeitenden sind beteiligt.',pts:['Standards als Basis','ständige Verbesserung','kleine Schritte','alle beteiligt']},
 {id:'PF105',ch:'KVP und Vorschlagswesen',q:'Erläutern Sie die vier Schritte des PDCA-Zyklus.',a:'Plan: Ursache klären und Maßnahme planen; Do: im Kleinen umsetzen; Check: Wirkung prüfen; Act: als Standard festschreiben.',pts:['Plan: planen','Do: erproben','Check: prüfen','Act: standardisieren']},
 {id:'PF106',ch:'KVP und Vorschlagswesen',q:'Nennen Sie vier Arten von Verschwendung im Lean-Gedanken.',a:'Z. B. Überproduktion, Wartezeit, unnötiger Transport und Fehler (auch Bestände, Wege, unnötige Bearbeitung).',pts:['Überproduktion','Wartezeit','Transport','Fehler']},
 {id:'PF107',ch:'KVP und Vorschlagswesen',q:'Unterscheiden Sie KVP und betriebliches Vorschlagswesen.',a:'KVP ist eine dauernde, oft gruppenbezogene Verbesserung im eigenen Arbeitsbereich; das BVW prämiert einzelne Vorschläge, die über die eigene Aufgabe hinausgehen.',pts:['KVP: dauerhaft, im eigenen Bereich','BVW: Einzelvorschläge','BVW: über eigene Aufgabe hinaus','BVW: Prämie']},
 {id:'PF108',ch:'KVP und Vorschlagswesen',q:'Welches Recht hat der Betriebsrat beim betrieblichen Vorschlagswesen?',a:'Mitbestimmung bei den Grundsätzen des Vorschlagswesens (§ 87 Abs. 1 Nr. 12 BetrVG), meist geregelt in einer Betriebsvereinbarung.',pts:['Mitbestimmung','§ 87 Abs. 1 Nr. 12','Betriebsvereinbarung']},
 {id:'PF109',ch:'KVP und Vorschlagswesen',q:'Beschreiben Sie den Ablauf eines Verbesserungsvorschlags.',a:'Einreichen mit Eingangsbestätigung, Begutachtung, Entscheidung und Prämienberechnung, Mitteilung durch Vorgesetzte und Umsetzung.',pts:['Eingangsbestätigung','Gutachten','Entscheidung und Prämie','Mitteilung und Umsetzung']},
 {id:'PF110',ch:'KVP und Vorschlagswesen',q:'Wie berechnet man die Prämie für einen Verbesserungsvorschlag?',a:'Nettoersparnis im ersten Jahr (Bruttoersparnis minus Umsetzungskosten) mal Prämiensatz laut Betriebsvereinbarung.',tex:'P_\\text{r} = (E_\\text{brutto} - K_\\text{U}) \\cdot p',pts:['Bruttoersparnis minus Kosten','mal Prämiensatz','Betriebsvereinbarung']},
 {id:'PF111',ch:'KVP und Vorschlagswesen',q:'Ersparnis 10.000 €/Jahr, Umsetzungskosten 2.000 €, Prämiensatz 20 %. Wie hoch ist die Prämie?',a:'Nettoersparnis 8.000 €; Prämie 8.000 € · 0,2 = 1.600 €.',pts:['Nettoersparnis 8.000 €','Prämie 1.600 €']},
 {id:'PF112',ch:'KVP und Vorschlagswesen',q:'Warum scheitert ein Vorschlagswesen häufig in der Praxis?',a:'Wegen langer bürokratischer Bearbeitung, fehlender Rückmeldung und Vorgesetzten, die Vorschläge als Kritik empfinden.',pts:['lange Bearbeitung','fehlende Rückmeldung','Vorgesetzte fühlen sich kritisiert']},
 {id:'PF113',ch:'Gruppen und Moderation',q:'Nennen Sie vier Vorteile der Gruppenarbeit.',a:'Mehr Informationen und Ideen, bessere Problemlösung, gegenseitige Unterstützung, höhere Motivation und Flexibilität.',pts:['mehr Ideen','bessere Problemlösung','gegenseitige Unterstützung','Flexibilität']},
 {id:'PF114',ch:'Gruppen und Moderation',q:'Was kennzeichnet eine teilautonome Arbeitsgruppe?',a:'Sie erstellt ein (Teil-)Produkt und regelt Aufgabenverteilung, Arbeitszeit und teilweise Methoden selbst.',pts:['eigenes (Teil-)Produkt','Selbstregelung der Aufgabenverteilung','Mitsprache bei Zeit und Methoden']},
 {id:'PF115',ch:'Gruppen und Moderation',q:'Welches Mitbestimmungsrecht hat der Betriebsrat bei Gruppenarbeit?',a:'Er bestimmt bei den Grundsätzen über die Durchführung von Gruppenarbeit mit (§ 87 Abs. 1 Nr. 13 BetrVG).',pts:['Mitbestimmung','Grundsätze der Gruppenarbeit','§ 87 Abs. 1 Nr. 13']},
 {id:'PF116',ch:'Gruppen und Moderation',q:'Nennen Sie vier Merkmale eines Projekts.',a:'Einmaligkeit, klares Ziel, zeitliche und finanzielle Begrenzung, eigene Projektorganisation.',pts:['Einmaligkeit','klares Ziel','begrenzte Zeit und Mittel','eigene Organisation']},
 {id:'PF117',ch:'Gruppen und Moderation',q:'Nennen Sie die Phasen der Teamentwicklung nach Tuckman.',a:'Forming, Storming, Norming, Performing und Adjourning.',pts:['Forming','Storming','Norming','Performing','Adjourning']},
 {id:'PF118',ch:'Gruppen und Moderation',q:'Was tut der Meister in der Storming-Phase?',a:'Konflikte zulassen und moderieren, Rollen klären und Kommunikationsregeln vereinbaren.',pts:['Konflikte moderieren','Rollen klären','Regeln vereinbaren']},
 {id:'PF119',ch:'Gruppen und Moderation',q:'Nach welchen Kriterien stellen Sie eine Projektgruppe für einen Eilauftrag zusammen?',a:'Fachliche Abdeckung aller Bereiche, Problemlöse- und Kommunikationsfähigkeit, Teamfähigkeit und Verantwortungsbewusstsein; heterogen zusammensetzen.',pts:['alle Fachbereiche abgedeckt','Problemlösefähigkeit','Teamfähigkeit','heterogene Zusammensetzung']},
 {id:'PF120',ch:'Gruppen und Moderation',q:'Welche Eigenschaften braucht ein Moderator?',a:'Neutralität, Methodensicherheit, Flexibilität und Fähigkeit, Konflikte zu erkennen und zum Konsens zu führen.',pts:['Neutralität','Methodensicherheit','Flexibilität','Konsensfähigkeit']},
 {id:'PF121',ch:'Gruppen und Moderation',q:'Nennen Sie die typischen Schritte einer Moderation.',a:'Einstieg, Themen sammeln, auswählen, bearbeiten, Maßnahmen planen, Abschluss.',pts:['Einstieg','sammeln','auswählen','bearbeiten','Maßnahmenplan','Abschluss']},
 {id:'PF122',ch:'Gruppen und Moderation',q:'Was gehört in einen Maßnahmenplan nach einer Besprechung?',a:'Was zu tun ist, wer verantwortlich ist und bis wann – mit Kontrolltermin.',pts:['Was','Wer','Bis wann','Kontrolltermin']},
 {id:'PF123',ch:'Gruppen und Moderation',q:'Erläutern Sie die 6-3-5-Methode.',a:'Sechs Personen schreiben je drei Ideen in fünf Minuten und reichen das Blatt weiter; so entstehen bis zu 108 Ideen.',pts:['6 Personen','3 Ideen','5 Minuten','Blatt weitergeben']},
 {id:'PF124',ch:'Gruppen und Moderation',q:'Was ist eine Kraftfeldanalyse?',a:'Gegenüberstellung der Kräfte, die ein Ziel fördern, und der Kräfte, die es hemmen; Förderer werden gestärkt, Hemmnisse abgebaut.',pts:['fördernde Kräfte','hemmende Kräfte','Förderer stärken, Hemmnisse abbauen']},
 {id:'PF125',ch:'Gruppen und Moderation',q:'Wie erstellen Sie ein Ishikawa-Diagramm?',a:'Wirkung an den Kopf schreiben, Ursachenfelder Mensch, Maschine, Material, Methode als Gräten anlegen und je Feld konkrete Ursachen eintragen; dann die wahrscheinlichsten prüfen.',pts:['Wirkung am Kopf','Mensch, Maschine, Material, Methode','konkrete Ursachen je Feld','wahrscheinlichste Ursache prüfen']},
 {id:'PF126',ch:'Gruppen und Moderation',q:'Welche Grundregel gilt beim Brainstorming?',a:'Ideen werden ohne Kritik gesammelt; Menge geht vor Qualität, bewertet wird erst danach.',pts:['keine Kritik','Menge vor Qualität','später bewerten']},
 {id:'PF127',ch:'Führungsstile und -modelle',q:'Was beschreibt das 3-D-Modell von Reddin?',a:'Reddin erweitert die Dimensionen Aufgaben- und Beziehungsorientierung um die Effektivität. Derselbe Führungsstil kann je nach Situation effektiv oder ineffektiv sein: Der Integrator ist effektiv, der Kompromissler ineffektiv, der Verwalter wirkt im richtigen Umfeld, der Autokrat nicht. Kein Stil ist an sich der beste.',pts:['Aufgabenorientierung','Beziehungsorientierung','Effektivität als dritte Dimension','situationsabhängig']},
 {id:'PF128',ch:'Führungsstile und -modelle',q:'Was sagt das Kontinuum-Modell von Tannenbaum und Schmidt aus?',a:'Führungsstile reichen vom autoritären Befehl bis zur Entscheidung durch die Gruppe. Je größer der Entscheidungsspielraum der Mitarbeiter, desto kooperativer der Stil. Welcher passt, hängt von Führungskraft, Mitarbeitern und Situation ab.',pts:['Kontinuum autoritär bis partizipativ','Entscheidungsspielraum','abhängig von Situation']},
 {id:'PF129',ch:'Führungsstile und -modelle',q:'Wie unterscheiden sich Theorie X und Theorie Y nach McGregor?',a:'Theorie X unterstellt, Menschen arbeiteten ungern und müssten kontrolliert und geführt werden. Theorie Y geht davon aus, dass Menschen Verantwortung suchen, sich mit Zielen identifizieren und selbst steuern, wenn die Bedingungen stimmen. Aus X folgt eher autoritäres, aus Y kooperatives Führen.',pts:['X Kontrolle und Zwang','Y Selbststeuerung','Menschenbild','autoritär versus kooperativ']},
 {id:'PF130',ch:'Führungsstile und -modelle',q:'Wie unterscheiden sich transaktionale und transformationale Führung?',a:'Transaktionale Führung basiert auf Austausch: Leistung gegen Belohnung, klare Ziele und Kontrolle nach Abweichungen. Transformationale Führung motiviert durch Vision, Vorbild, individuelle Förderung und Sinn, um Mitarbeiter über das Erwartete hinaus zu bringen.',pts:['Austausch Leistung gegen Belohnung','Vision und Vorbild','individuelle Förderung']},
 {id:'PF131',ch:'Führungsstile und -modelle',q:'Was bedeutet Management by Exception?',a:'Die Führungskraft greift nur ein, wenn Abweichungen von vereinbarten Zielen oder Toleranzen auftreten. Das entlastet die Führung und gibt Freiraum, setzt aber klare Toleranzgrenzen und funktionierende Berichte voraus; Gefahr ist, dass Gutes nicht gewürdigt wird.',pts:['Eingriff nur bei Abweichung','Toleranzgrenzen','Entlastung','Gefahr fehlende Anerkennung']},
 {id:'PF132',ch:'Führungsstile und -modelle',q:'Was ist Management by Objectives und welche Voraussetzungen hat es?',a:'Führen durch Zielvereinbarung: Vorgesetzter und Mitarbeiter vereinbaren messbare Ziele, der Mitarbeiter wählt den Weg, am Ende wird das Ergebnis besprochen. Voraussetzungen: SMART formulierte Ziele, Kompetenzen und Ressourcen, regelmäßige Rückmeldung und eine Kultur des Vertrauens.',pts:['Ziele vereinbaren','Mitarbeiter wählt Weg','SMART','Rückmeldung']},
 {id:'PF133',ch:'Führungsstile und -modelle',q:'Was ist beim Führen auf Distanz und bei mobilem Arbeiten zu beachten?',a:'Klare Ziele und Ergebnisse statt Anwesenheit, feste Kommunikationsrituale (Teambesprechung, Einzelgespräche), Erreichbarkeitsregeln, geeignete Technik, Vertrauen und regelmäßiges Feedback. Arbeitszeit- und Datenschutz bleiben einzuhalten, Isolation ist zu vermeiden.',pts:['Ergebnisse statt Anwesenheit','feste Rituale','Erreichbarkeitsregeln','Vertrauen','Arbeitszeit und Datenschutz']},
 {id:'PF134',ch:'Führungsstile und -modelle',q:'Wie geht man mit unterschiedlichen Generationen und Vielfalt (Diversity) im Team um?',a:'Unterschiede in Erfahrungen, Erwartungen und Arbeitsweisen anerkennen, Stärken nutzen (gemischte Teams, gegenseitiges Lernen, Mentoring), Vorurteile abbauen, einheitliche Regeln anwenden und das Allgemeine Gleichbehandlungsgesetz (AGG) beachten.',pts:['Unterschiede anerkennen','gemischte Teams','Mentoring','Vorurteile abbauen','AGG beachten']},
 {id:'PF135',ch:'Motivation',q:'Was besagt die Erwartungstheorie von Vroom?',a:'Motivation entsteht aus drei Einschätzungen: Erwartung (Führt meine Anstrengung zur Leistung?), Instrumentalität (Führt die Leistung zu einem Ergebnis?) und Valenz (Ist mir das Ergebnis wichtig?). Ist einer der Faktoren null, entfällt die Motivation.',pts:['Erwartung','Instrumentalität','Valenz','Produkt der Faktoren']},
 {id:'PF136',ch:'Motivation',q:'Was beschreibt die Equity-Theorie von Adams?',a:'Menschen vergleichen das Verhältnis von eigenem Einsatz und Ertrag mit dem anderer. Empfinden sie Ungerechtigkeit, versuchen sie sie auszugleichen: Einsatz senken, Ertrag erhöhen, Vergleich ändern oder wechseln. Für Führungskräfte heißt das: transparente, faire Bewertung und Entlohnung.',pts:['Einsatz-Ertrags-Verhältnis','sozialer Vergleich','Ungerechtigkeit','faire Bewertung']},
 {id:'PF137',ch:'Motivation',q:'Wie lassen sich Burnout und Stress im Team frühzeitig erkennen und mindern?',a:'Warnzeichen: Leistungsabfall, Rückzug, Gereiztheit, häufige Fehlzeiten. Maßnahmen: Gespräch suchen, Arbeitslast und Prioritäten klären, Pausen und Erholung sichern, Unterstützung anbieten, Beratungsangebote und Betriebsarzt einbinden, Ursachen in der Arbeitsorganisation beseitigen. Eine Diagnose stellt der Meister nicht.',pts:['Warnzeichen','Gespräch','Arbeitslast klären','Pausen','Betriebsarzt','keine Diagnose durch Meister']},
 {id:'PF138',ch:'Kommunikation',q:'Wie unterscheiden sich Sender-Empfänger-Modell und Vier-Seiten-Modell?',a:'Das einfache Sender-Empfänger-Modell beschreibt Codierung, Kanal und Decodierung einer Botschaft mit möglichen Störungen. Das Vier-Seiten-Modell von Schulz von Thun zeigt, dass jede Nachricht Sachinhalt, Selbstoffenbarung, Beziehung und Appell enthält und der Empfänger auf vier Ohren hört.',pts:['Sender Kanal Empfänger Störung','Sachinhalt','Selbstoffenbarung','Beziehung','Appell']},
 {id:'PF139',ch:'Kommunikation',q:'Was bedeutet die Aussage „Man kann nicht nicht kommunizieren“?',a:'Es ist das erste Axiom von Watzlawick: Jedes Verhalten, auch Schweigen, hat Mitteilungscharakter. Weitere Axiome: Inhalts- und Beziehungsaspekt, Interpunktion von Ereignisfolgen, digitale und analoge Kommunikation, symmetrisch und komplementär.',pts:['jedes Verhalten kommuniziert','Inhalt und Beziehung','Interpunktion','digital analog']},
 {id:'PF140',ch:'Konfliktmanagement',q:'Was zeigt das Eskalationsmodell von Glasl?',a:'Konflikte verlaufen in neun Stufen und drei Phasen: Stufe 1 bis 3 (Verhärtung, Debatte, Taten statt Worte) sind noch win-win möglich, Stufe 4 bis 6 (Images und Koalitionen, Gesichtsverlust, Drohstrategien) win-lose, Stufe 7 bis 9 (begrenzte Vernichtungsschläge, Zersplitterung, gemeinsam in den Abgrund) lose-lose. Je höher die Stufe, desto eher ist Hilfe von außen nötig (Moderation, Mediation, Machteingriff).',pts:['neun Stufen','drei Phasen','win-win win-lose lose-lose','Hilfe von außen']},
 {id:'PF141',ch:'Konfliktmanagement',q:'Wie läuft eine Mediation ab und was unterscheidet sie vom Schiedsspruch?',a:'Ein neutraler Dritter ohne Entscheidungsbefugnis führt die Parteien durch Phasen: Einführung, Sichtweisen darstellen, Interessen klären, Lösungen sammeln, Vereinbarung treffen. Die Lösung erarbeiten die Beteiligten selbst und freiwillig; ein Schiedsspruch dagegen wird vom Dritten verbindlich festgelegt.',pts:['neutraler Dritter','freiwillig','Interessen klären','Lösung selbst erarbeiten','keine Entscheidung durch Mediator']},
 {id:'PF142',ch:'Gruppen und Moderation',q:'Welche Teamrollen beschreibt Belbin und warum sind sie wichtig?',a:'Belbin unterscheidet neun Rollen in drei Gruppen: handlungsorientiert (Macher, Umsetzer, Perfektionist), kommunikationsorientiert (Koordinator, Teamarbeiter, Weichensteller) und wissensorientiert (Neuerer, Beobachter, Spezialist). Ein erfolgreiches Team deckt die Rollen ab und nutzt die Stärken.',pts:['neun Rollen','handlungsorientiert','kommunikationsorientiert','wissensorientiert','Rollen abdecken']},
 {id:'PF143',ch:'Veränderung',q:'Wie läuft ein Veränderungsprozess nach Lewin ab?',a:'Drei Phasen: Auftauen (Unfreezing) – Veränderungsbedarf verdeutlichen und Bereitschaft schaffen; Verändern (Moving) – neue Verhaltensweisen einführen; Einfrieren (Refreezing) – Neues verankern und stabilisieren. Widerstände werden ernst genommen.',pts:['Unfreezing','Moving','Refreezing','Widerstände ernst nehmen']},
 {id:'PF144',ch:'Veränderung',q:'Welche acht Schritte nennt Kotter für erfolgreichen Wandel?',a:'1. Dringlichkeit erzeugen, 2. Führungskoalition bilden, 3. Vision und Strategie entwickeln, 4. Vision kommunizieren, 5. Hindernisse beseitigen und Mitarbeiter befähigen, 6. kurzfristige Erfolge sichtbar machen, 7. Erfolge ausbauen, 8. Veränderungen in der Kultur verankern.',pts:['Dringlichkeit','Führungskoalition','Vision','kurzfristige Erfolge','Kultur verankern']},
 {id:'PF145',ch:'Veränderung',q:'Wie begegnet der Meister Widerständen gegen Veränderungen?',a:'Ursachen verstehen (Angst um Arbeitsplatz, Gewohnheit, fehlende Information), frühzeitig und ehrlich informieren, Betroffene beteiligen, Nutzen verdeutlichen, Qualifizierung anbieten, Bedenken ernst nehmen und kleine Erfolge sichtbar machen.',pts:['Ursachen verstehen','früh informieren','Betroffene beteiligen','Qualifizierung','Erfolge zeigen']},
 {id:'PF146',ch:'Arbeitsrecht',q:'Welche Kündigungsarten gibt es und welche Fristen gelten nach § 622 BGB?',a:'Ordentliche Kündigung unter Einhaltung der Frist, außerordentliche (fristlose) Kündigung aus wichtigem Grund. Grundfrist: vier Wochen zum 15. oder zum Ende eines Kalendermonats; in der Probezeit (bis sechs Monate) zwei Wochen. Für Arbeitgeber verlängert sich die Frist mit der Betriebszugehörigkeit (ab zwei Jahre einen Monat zum Monatsende, bis zu sieben Monate nach 20 Jahren).',pts:['ordentlich und außerordentlich','vier Wochen','Probezeit zwei Wochen','verlängert nach Betriebszugehörigkeit']},
 {id:'PF147',ch:'Arbeitsrecht',q:'Welche Voraussetzungen hat die fristlose Kündigung nach § 626 BGB?',a:'Es muss ein wichtiger Grund vorliegen, der die Fortsetzung bis zum Ende der Frist unzumutbar macht, nach Abwägung beider Interessen. Die Kündigung muss innerhalb von zwei Wochen ab Kenntnis der Tatsachen erklärt werden. Meist geht eine Abmahnung voraus, außer bei schwersten Verstößen; der Betriebsrat ist anzuhören.',pts:['wichtiger Grund','zwei Wochen ab Kenntnis','Interessenabwägung','Abmahnung','Betriebsrat anhören']},
 {id:'PF148',ch:'Arbeitsrecht',q:'Wann gilt das Kündigungsschutzgesetz und welche Kündigungsgründe sind sozial gerechtfertigt?',a:'Es gilt in Betrieben mit mehr als zehn Arbeitnehmern (Teilzeit anteilig, Auszubildende nicht gezählt) für Beschäftigte nach sechs Monaten Betriebszugehörigkeit. Gründe: personenbedingt (z. B. Krankheit), verhaltensbedingt (nach Abmahnung) oder betriebsbedingt (dringende Erfordernisse, Sozialauswahl). Klage binnen drei Wochen.',pts:['mehr als zehn Arbeitnehmer','sechs Monate','personen verhaltens betriebsbedingt','Sozialauswahl','Klage in drei Wochen']},
 {id:'PF149',ch:'Arbeitsrecht',q:'Welche Rechte hat der Betriebsrat vor einer Kündigung nach § 102 BetrVG?',a:'Der Arbeitgeber muss den Betriebsrat vor jeder Kündigung anhören und die Gründe mitteilen. Der Betriebsrat kann innerhalb einer Woche Bedenken (ordentliche Kündigung) bzw. drei Tagen (außerordentliche Kündigung) äußern oder widersprechen. Ohne ordnungsgemäße Anhörung ist die Kündigung unwirksam.',pts:['vor jeder Kündigung anhören','eine Woche','drei Tage','ohne Anhörung unwirksam']},
 {id:'PF150',ch:'Arbeitsrecht',q:'Welche Mitbestimmungsrechte hat der Betriebsrat bei sozialen und personellen Angelegenheiten?',a:'Bei sozialen Angelegenheiten (§ 87 BetrVG) besteht Mitbestimmung z. B. bei Arbeitszeit, Pausen, Urlaubsgrundsätzen, Verhaltensregeln, Überwachungstechnik und Entgeltgrundsätzen. Bei Einstellung, Versetzung, Eingruppierung und Umgruppierung (§ 99) ist die Zustimmung erforderlich; er kann sie aus gesetzlichen Gründen verweigern.',pts:['§ 87 soziale Angelegenheiten','Arbeitszeit Pausen Überwachung','§ 99 personelle Einzelmaßnahmen','Zustimmung verweigern']},
 {id:'PF151',ch:'Arbeitsrecht',q:'Was gilt bei befristeten Arbeitsverträgen nach dem TzBfG?',a:'Befristung braucht Schriftform. Ohne sachlichen Grund ist sie bis zu zwei Jahren zulässig, höchstens dreimal verlängerbar, und nur wenn zuvor kein Arbeitsverhältnis mit demselben Arbeitgeber bestand. Mit sachlichem Grund (z. B. Vertretung, Projekt) sind längere Befristungen möglich. Befristete dürfen nicht schlechter behandelt werden.',pts:['Schriftform','zwei Jahre ohne Sachgrund','dreimal verlängern','kein Vorbeschäftigung','Sachgrund Vertretung']},
 {id:'PF152',ch:'Arbeitsrecht',q:'Was regeln Tarifvertrag und Betriebsvereinbarung und wie stehen sie zueinander?',a:'Tarifverträge schließen Gewerkschaften und Arbeitgeber(verbände) über Entgelt und Arbeitsbedingungen ab (Tarifautonomie). Betriebsvereinbarungen schließen Betriebsrat und Arbeitgeber für den Betrieb. Regelungen, die üblicherweise tariflich geregelt werden, dürfen nicht Gegenstand einer Betriebsvereinbarung sein (Tarifvorrang); das Günstigkeitsprinzip schützt den Arbeitnehmer.',pts:['Gewerkschaft und Arbeitgeberverband','Tarifautonomie','Betriebsrat und Arbeitgeber','Tarifvorrang','Günstigkeitsprinzip']},
 {id:'PF153',ch:'Arbeitsrecht',q:'Welche Regeln gelten für Urlaub und Entgeltfortzahlung im Krankheitsfall?',a:'Der gesetzliche Mindesturlaub beträgt 24 Werktage bei sechs Arbeitstagen, also 20 Tage bei einer Fünf-Tage-Woche. Bei Krankheit zahlt der Arbeitgeber das Entgelt bis zu sechs Wochen weiter; die Erkrankung ist unverzüglich zu melden und bei mehr als drei Tagen ärztlich zu belegen (elektronische Meldung). Tarifvertraglich sind oft mehr Urlaubstage geregelt.',pts:['24 Werktage Mindesturlaub','20 Tage bei Fünf-Tage-Woche','sechs Wochen Entgeltfortzahlung','unverzüglich melden','Bescheinigung ab dem vierten Tag']},
 {id:'PF154',ch:'Arbeitsrecht',q:'Was verbietet das Allgemeine Gleichbehandlungsgesetz (AGG) und was sind Pflichten des Arbeitgebers?',a:'Benachteiligung wegen ethnischer Herkunft, Geschlecht, Religion, Weltanschauung, Behinderung, Alter oder sexueller Identität. Der Arbeitgeber muss vorbeugen, eine Beschwerdestelle einrichten, bei Verstößen einschreiten und Schadensersatz bzw. Entschädigung leisten können. Das gilt bei Einstellung, Beförderung, Entgelt und Kündigung.',pts:['ethnische Herkunft','Geschlecht','Religion Weltanschauung','Behinderung','Alter','sexuelle Identität','Beschwerdestelle']},
 {id:'PF155',ch:'Arbeitsrecht',q:'Welche Anforderungen stellt der Datenschutz (DSGVO) an die Personalarbeit?',a:'Personenbezogene Daten dürfen nur für den vorgesehenen Zweck verarbeitet werden (Zweckbindung, Datenminimierung), brauchen eine Rechtsgrundlage (Vertrag, Gesetz, Einwilligung), sind zu schützen und nach Wegfall des Zwecks zu löschen. Beschäftigte haben Auskunfts-, Berichtigungs- und Löschrechte; der Meister gibt Personaldaten nicht unbefugt weiter.',pts:['Zweckbindung','Datenminimierung','Rechtsgrundlage','Löschung','Auskunftsrecht']},
 {id:'PF156',ch:'Kommunikation',q:'Was ist das Johari-Fenster und wie nutzt man es für Feedback?',a:'Vier Felder aus „mir bekannt/unbekannt“ und „anderen bekannt/unbekannt“: öffentliche Person (beiden bekannt), blinder Fleck (anderen bekannt, mir nicht), Fassade (nur mir bekannt), Unbekanntes. Feedback verkleinert den blinden Fleck, Offenheit die Fassade. Ziel ist eine größere öffentliche Fläche für Vertrauen und Zusammenarbeit.',pts:['öffentliche Person','blinder Fleck','Fassade','Unbekanntes','Feedback Offenheit']},
 {id:'PF157',ch:'Kommunikation',q:'Welche Regeln gelten für gutes Feedback?',a:'Zeitnah und konkret, beschreibend statt wertend (Beobachtung, Wirkung, Wunsch), in Ich-Botschaften, ausgewogen (Positives und Verbesserungsfelder), nur zu veränderbarem Verhalten, unter vier Augen bei Kritik. Der Empfänger darf Rückfragen stellen und entscheidet, was er annimmt.',pts:['zeitnah konkret','beschreiben statt werten','Ich-Botschaft','unter vier Augen','Rückfragen']},
 {id:'PF158',ch:'Kommunikation',q:'Was ist aktives Zuhören und welche Techniken gehören dazu?',a:'Dem Gegenüber volle Aufmerksamkeit geben, Blickkontakt, nicken, nachfragen (offene Fragen), Paraphrasieren (Gesagtes in eigenen Worten wiedergeben), Verbalisieren von Gefühlen, Zusammenfassen und Pausen aushalten. Es verhindert Missverständnisse und zeigt Wertschätzung.',pts:['volle Aufmerksamkeit','offene Fragen','Paraphrasieren','Zusammenfassen']},
 {id:'PF159',ch:'Gesprächsführung',q:'Wie läuft ein Kritikgespräch in Phasen ab?',a:'Vorbereiten (Fakten, Ziel, Ort), sachlich beginnen und Anlass nennen, Sichtweise des Mitarbeiters anhören, Auswirkungen erklären, gemeinsam Lösungen erarbeiten, Vereinbarung mit Termin treffen, positiv abschließen und nachfassen. Kritik betrifft das Verhalten, nicht die Person.',pts:['vorbereiten','Anlass nennen','Mitarbeiter anhören','Lösung vereinbaren','nachfassen']},
 {id:'PF160',ch:'Gesprächsführung',q:'Was gehört in ein Zielvereinbarungsgespräch und wie formuliert man SMART?',a:'Ziele mit Bezug zur Unternehmensstrategie, Messgrößen, Termin, Ressourcen und Unterstützung, Zwischenstände. SMART: spezifisch, messbar, attraktiv (akzeptiert), realistisch, terminiert. Ergebnis wird schriftlich festgehalten und im Beurteilungsgespräch geprüft.',pts:['Strategiebezug','Messgrößen Termin','spezifisch messbar attraktiv realistisch terminiert','schriftlich']},
 {id:'PF161',ch:'Gesprächsführung',q:'Wie führt man ein Rückkehr- oder Fehlzeitengespräch?',a:'Persönlich Interesse zeigen, Hilfe anbieten, Arbeitsplatzbedingungen besprechen, ohne Diagnosen zu verlangen (Datenschutz). Bei häufigen Fehlzeiten: Muster ansprechen, Unterstützung (BEM), klare Erwartungen und Folgen. Gesprächsinhalte vertraulich dokumentieren.',pts:['Interesse Hilfe','keine Diagnose verlangen','BEM','vertraulich']},
 {id:'PF162',ch:'Delegation',q:'Wann ist Delegation nicht zulässig oder nicht sinnvoll?',a:'Nicht delegiert werden Führungsaufgaben wie Zielsetzung, Personalauswahl und -beurteilung, Disziplinarmaßnahmen, Motivation und Kontrolle als Gesamtverantwortung, Aufgaben, die Vertraulichkeit verlangen, sowie Aufgaben, für die Mitarbeiter nicht qualifiziert sind oder keine Befugnis haben. Die Gesamtverantwortung bleibt bei der Führungskraft.',pts:['Führungsaufgaben nicht','Personalentscheidungen','fehlende Qualifikation','Gesamtverantwortung bleibt']},
 {id:'PF163',ch:'Konfliktmanagement',q:'Welche Strategien gibt es zur Konfliktlösung (Thomas-Kilmann)?',a:'Wettbewerben (durchsetzen), Nachgeben (anpassen), Vermeiden (ausweichen), Kompromiss (Mitte) und Zusammenarbeiten (win-win, gemeinsame Lösung). Je nach Wichtigkeit des Themas und der Beziehung ist eine andere Strategie angemessen; dauerhaft tragfähig ist meist die Zusammenarbeit.',pts:['Wettbewerben Nachgeben Vermeiden','Kompromiss','Zusammenarbeiten win-win']},
 {id:'PF164',ch:'Konfliktmanagement',q:'Was besagt das Harvard-Konzept für sachgerechtes Verhandeln?',a:'Menschen und Probleme getrennt behandeln, auf Interessen statt Positionen achten, Entscheidungsmöglichkeiten zum beiderseitigen Vorteil entwickeln und auf objektiven Beurteilungskriterien bestehen. Ziel ist eine faire, tragfähige Einigung.',pts:['Mensch und Problem trennen','Interessen statt Positionen','Optionen entwickeln','objektive Kriterien']},
 {id:'PF165',ch:'Gruppen und Moderation',q:'Wie leitet man eine Besprechung wirksam?',a:'Ziel und Agenda vorher klären, Teilnehmer auswählen, Zeit einhalten, pünktlich beginnen, Moderation strukturiert (Regeln, Redezeit), Ergebnisse visualisieren, Protokoll mit Maßnahmen, Verantwortlichen und Termin, Nachverfolgung. Nur treffen, wenn es nötig ist.',pts:['Ziel und Agenda','Zeitrahmen','visualisieren','Maßnahmen Verantwortliche Termin']},
 {id:'PF166',ch:'Gruppen und Moderation',q:'Welche Methoden der Entscheidungsfindung im Team kennen Sie?',a:'Konsens, Mehrheitsentscheid, Entscheid durch die Führungskraft nach Beratung, Nutzwertanalyse (Kriterien gewichten und bewerten), Paarvergleich, Punktabfrage und Entscheidungsmatrix. Wahl nach Zeit, Tragweite und Akzeptanz: je wichtiger die Akzeptanz, desto mehr Beteiligung.',pts:['Konsens','Mehrheit','Nutzwertanalyse','Paarvergleich','Akzeptanz']},
 {id:'PF167',ch:'Gruppen und Moderation',q:'Was ist Zeitmanagement nach Eisenhower und ALPEN?',a:'Eisenhower-Matrix: Aufgaben nach wichtig/unwichtig und dringend/nicht dringend (selbst erledigen, terminieren, delegieren, streichen). ALPEN-Methode: Aufgaben notieren, Länge schätzen, Pufferzeiten einplanen, Entscheidungen über Prioritäten treffen, Nachkontrolle. Hinzu kommen Pareto (80/20) und Zeitfresser-Analyse.',pts:['wichtig dringend Matrix','ALPEN','Puffer','Pareto']},
 {id:'PF168',ch:'Personalbedarf',q:'Wie berechnet man Fluktuations- und Krankenquote?',a:'Fluktuationsquote = Abgänge (ohne Altersabgänge) / durchschnittlicher Personalbestand · 100. Krankenquote = Fehltage durch Krankheit / Soll-Arbeitstage (Sollarbeitstage mal Mitarbeiter) · 100. Beide sind Frühindikatoren für Betriebsklima und Führungsqualität; hohe Werte erfordern Ursachenanalyse.',pts:['Abgänge durch Durchschnittsbestand','Fehltage durch Sollarbeitstage','Frühindikator']},
 {id:'PF169',ch:'Arbeitsrecht',q:'Welche Aussagen enthält ein einfaches und ein qualifiziertes Arbeitszeugnis?',a:'Das einfache Zeugnis nennt Person, Dauer und Art der Tätigkeit. Das qualifizierte beurteilt zusätzlich Leistung und Verhalten. Es muss wohlwollend, aber wahr und klar formuliert sein; Geheimcodes sind unzulässig. Der Arbeitnehmer hat Anspruch auf ein Zeugnis bei Beendigung (§ 109 GewO); auf Wunsch auch ein Zwischenzeugnis.',pts:['einfach Dauer und Art','qualifiziert Leistung und Verhalten','wohlwollend und wahr','Anspruch bei Beendigung']},
 {id:'PF170',ch:'Arbeitsrecht',q:'Wann ist eine Abmahnung nötig und wie muss sie aussehen?',a:'Bei verhaltensbedingten Pflichtverletzungen ist vor einer Kündigung meist eine Abmahnung nötig: Sie beschreibt den Verstoß konkret (Datum, Ort, Hergang), fordert vertragsgemäßes Verhalten (Rüge) und kündigt Konsequenzen an (Warnfunktion). Zeitnah erteilen und in die Personalakte nehmen; Mitarbeiter kann Stellung nehmen.',pts:['Verstoß konkret','Rügefunktion','Warnfunktion','zeitnah','Personalakte']},
 {id:'PF171',ch:'Arbeitsrecht',q:'Welche Rechte hat der Arbeitgeber aufgrund des Weisungsrechts?',a:'Er bestimmt Inhalt, Ort und Zeit der Arbeit nach billigem Ermessen im Rahmen von Gesetz, Tarifvertrag, Betriebsvereinbarung und Arbeitsvertrag (§ 106 GewO). Unzulässig sind Weisungen, die Gesetze verletzen oder die Persönlichkeitsrechte oder den Gesundheitsschutz missachten; Betriebsrat hat teils Mitbestimmungsrechte.',pts:['Inhalt Ort Zeit','billiges Ermessen','Grenzen Gesetz Vertrag','Mitbestimmung']},
 {id:'PF172',ch:'Arbeitsrecht',q:'Was gilt für Kurzarbeit?',a:'Kurzarbeit ist die vorübergehende Verkürzung der Arbeitszeit bei erheblichem Arbeitsausfall; sie muss einzelvertraglich, tarif- oder betrieblich geregelt sein und beim Betriebsrat mitbestimmt werden. Die Bundesagentur zahlt unter Voraussetzungen Kurzarbeitergeld (rund 60 bzw. 67 % des Nettoentgeltausfalls). Der Arbeitgeber zeigt den Arbeitsausfall an.',pts:['Arbeitszeit vorübergehend verkürzt','Regelung nötig','Betriebsrat','Kurzarbeitergeld 60 bzw. 67 Prozent']}
];
